// Remove raster dust and pinholes before any pixel boundary becomes a metal return.
export function cleanArtworkMask(input,w,h){let mask=Uint8Array.from(input);const pass=(a,dilate)=>{const out=new Uint8Array(a.length);for(let y=0;y<h;y++)for(let x=0;x<w;x++){let value=dilate?0:1;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const xx=x+dx,yy=y+dy,v=xx>=0&&yy>=0&&xx<w&&yy<h?a[yy*w+xx]:0;if(dilate)value|=v;else value&=v;}out[y*w+x]=value;}return out;};
 // Closing repairs tiny raster gaps. Opening removes spikes and isolated pixels.
 const paddedW=w+4,paddedH=h+4,padded=new Uint8Array(paddedW*paddedH);for(let y=0;y<h;y++)padded.set(mask.slice(y*w,(y+1)*w),(y+2)*paddedW+2);
 const morph=(a,W,H,dilate)=>{const out=new Uint8Array(a.length);for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++){let v=dilate?0:1;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(dilate)v|=a[(y+dy)*W+x+dx];else v&=a[(y+dy)*W+x+dx];}out[y*W+x]=v;}return out;};
 let p=morph(morph(padded,paddedW,paddedH,true),paddedW,paddedH,false);p=morph(morph(p,paddedW,paddedH,false),paddedW,paddedH,true);for(let y=0;y<h;y++)mask.set(p.slice((y+2)*paddedW+2,(y+2)*paddedW+2+w),y*w);
 const labels=new Int32Array(mask.length),areas=[0],queue=new Int32Array(mask.length);let label=0,total=mask.reduce((n,v)=>n+v,0);const neighbors=i=>{const x=i%w,y=Math.floor(i/w),out=[];if(x)out.push(i-1);if(x<w-1)out.push(i+1);if(y)out.push(i-w);if(y<h-1)out.push(i+w);return out;};
 for(let i=0;i<mask.length;i++)if(mask[i]&&!labels[i]){label++;let head=0,tail=1;queue[0]=i;labels[i]=label;while(head<tail){const k=queue[head++];for(const j of neighbors(k))if(mask[j]&&!labels[j]){labels[j]=label;queue[tail++]=j;}}areas.push(tail);}
 const minimum=Math.max(4,Math.round(total*.00008));for(let i=0;i<mask.length;i++)if(mask[i]&&areas[labels[i]]<minimum)mask[i]=0;
 const seen=new Uint8Array(mask.length);for(let i=0;i<mask.length;i++)if(!mask[i]&&!seen[i]){let head=0,tail=1,edge=false,owner=0;queue[0]=i;seen[i]=1;while(head<tail){const k=queue[head++],x=k%w,y=Math.floor(k/w);if(x===0||y===0||x===w-1||y===h-1)edge=true;for(const j of neighbors(k)){if(mask[j])owner=labels[j];else if(!seen[j]){seen[j]=1;queue[tail++]=j;}}}if(!edge&&tail<Math.max(8,(areas[owner]||0)*.006))for(let j=0;j<tail;j++)mask[queue[j]]=1;}
 return mask;
}
export function clippedReturnRings(contours,thickness,C){const scale=1e6;const paths=contours.map((points,i)=>{const p=points.map(([x,y])=>({X:Math.round(x*scale),Y:Math.round(y*scale)}));if(C.Clipper.Orientation(p)!==(i===0))p.reverse();return p;});const offset=new C.ClipperOffset(2,Math.max(5,thickness*scale*.015));offset.AddPaths(paths,C.JoinType.jtRound,C.EndType.etClosedPolygon);const inner=new C.Paths();offset.Execute(inner,-thickness*scale);const clipping=new C.Clipper();clipping.AddPaths(paths,C.PolyType.ptSubject,true);if(inner.length)clipping.AddPaths(inner,C.PolyType.ptClip,true);const tree=new C.PolyTree();clipping.Execute(C.ClipType.ctDifference,tree,C.PolyFillType.pftNonZero,C.PolyFillType.pftNonZero);const output=[],points=node=>node.Contour().map(p=>[p.X/scale,p.Y/scale]);const visit=node=>{if(node.Contour().length&&!node.IsHole())output.push({points:points(node),holes:node.Childs().filter(c=>c.IsHole()).map(points)});node.Childs().forEach(visit);};visit(tree);return output;}
